class ExchangeRateParity:
    def __init__(self, inflation_domestic, inflation_foreign, interest_domestic, interest_foreign, forward_premium=None):
        self.pi = inflation_domestic       # Yerel enflasyon oranı (π)
        self.pi_star = inflation_foreign   # Yabancı enflasyon oranı (π*)
        self.i = interest_domestic         # Yerel faiz oranı (i)
        self.i_star = interest_foreign     # Yabancı faiz oranı (i*)
        self.p = forward_premium           # Forward prim değeri (p)

    def inflation_difference(self):
        return self.pi - self.pi_star      # π - π*

    def interest_rate_difference(self):
        return self.i - self.i_star        # i - i*

    def expected_exchange_rate_change(self):
        # E(Δs) = i - i*
        return self.interest_rate_difference()

    def expected_exchange_rate_from_inflation(self):
        # E(Δs) = π - π*
        return self.inflation_difference()

    def interest_rate_from_inflation(self):
        # i - i* = E(π - π*)
        return self.inflation_difference()

    def interest_rate_from_forward(self):
        # i - i* = p
        return self.p

    def print_summary(self):
        print(f"Enflasyon farkı (π - π*): {self.inflation_difference():.2f}")
        print(f"Faiz oranı farkı (i - i*): {self.interest_rate_difference():.2f}")
        print(f"Beklenen döviz kuru değişimi (E(Δs)): {self.expected_exchange_rate_change():.2f}")
        if self.p is not None:
            print(f"Forward prim değeri (p): {self.p:.2f}")
            print(f"Faiz farkı = p denklemi kontrolü: {abs(self.interest_rate_difference() - self.p) < 1e-6}")

parity = ExchangeRateParity(inflation_domestic=0.45, inflation_foreign=0.03,
                            interest_domestic=0.10, interest_foreign=0.04,
                            forward_premium=0.06)

parity.print_summary()
